import React, { useState, useEffect, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import styles from './Profile.module.scss';
import ProfileHeader from '../../components/ProfileHeader/ProfileHeader';
import ProfileHeaderVisitor from '../../components/ProfileHeader/ProfileHeaderVisitor';
import About from '../../components/About/About';
import Bio from '../../components/Bio/Bio';
import PostsFeed from '../../components/PostsFeed/PostsFeed';
import FriendsList from '../../components/FriendsList/FriendsList';
import { useAuth } from '../../contexts/AuthContext';
import { api } from '../../utils/api';

export default function Profile() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { user: currentUser, isAuthenticated } = useAuth();
  const [profileUser, setProfileUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [friendStatus, setFriendStatus] = useState(null); // null, 'friends', 'pending_sent', 'pending_received', 'not_friends'
  const [error, setError] = useState(null);

  const checkFriendStatus = useCallback(async (user) => {
    if (!currentUser || !user) return;

    try {
      const userId = user.id || user.ID;

      // Check if already friends
      try {
        const friendsResponse = await api.get('/users/friends');
        if (friendsResponse && Array.isArray(friendsResponse)) {
          const isFriend = friendsResponse.some(friend => {
            const friendId = friend.id || friend.ID;
            return friendId === userId;
          });
          if (isFriend) {
            setFriendStatus('friends');
            return;
          }
        }
      } catch (err) {
        // Continue checking other statuses if friends check fails
        console.log('Friends check failed:', err);
      }

      // Check sent requests
      try {
        const sentResponse = await api.get('/users/friends/requests/sent');
        if (sentResponse && Array.isArray(sentResponse)) {
          const sentRequest = sentResponse.find(req => {
            const recipientId = req.recipient_id || req.RecipientID;
            const status = req.status || req.Status;
            return recipientId === userId && status === 'pending';
          });
          if (sentRequest) {
            setFriendStatus('pending_sent');
            return;
          }
        }
      } catch (err) {
        console.log('Sent requests check failed:', err);
      }

      // Check pending requests
      try {
        const pendingResponse = await api.get('/users/friends/requests/pending');
        if (pendingResponse && Array.isArray(pendingResponse)) {
          const pendingRequest = pendingResponse.find(req => {
            const senderId = req.sender_id || req.SenderID;
            const status = req.status || req.Status;
            return senderId === userId && status === 'pending';
          });
          if (pendingRequest) {
            setFriendStatus('pending_received');
            return;
          }
        }
      } catch (err) {
        console.log('Pending requests check failed:', err);
      }

      setFriendStatus('not_friends');
    } catch (err) {
      console.error('Failed to check friend status:', err);
      setFriendStatus('not_friends');
    }
  }, [currentUser]);

  useEffect(() => {
    if (!isAuthenticated) {
      navigate('/login');
      return;
    }

    const fetchProfile = async () => {
      try {
        setLoading(true);
        setError(null);

        // Determine if viewing own profile
        const isOwnProfile = !id || (currentUser && (String(currentUser.id || currentUser.ID) === String(id)));

        if (isOwnProfile) {
          // Fetch own profile
          const response = await api.get('/users/me');
          if (response.user) {
            setProfileUser(response.user);
          }
        } else {
          // Fetch other user's profile
          const response = await api.get(`/users/${id}`);
          if (response.data) {
            setProfileUser(response.data);
            // Check friend status for other users
            if (currentUser) {
              await checkFriendStatus(response.data);
            }
          }
        }
      } catch (err) {
        console.error('Failed to fetch profile:', err);
        setError(err.message || 'Failed to load profile');
      } finally {
        setLoading(false);
      }
    };

    if (isAuthenticated) {
      fetchProfile();
    }
  }, [id, isAuthenticated, currentUser, navigate, checkFriendStatus]);

  // Determine if viewing own profile
  const isOwnProfile = !id || (currentUser && profileUser && (String(currentUser.id || currentUser.ID) === String(profileUser.id || profileUser.ID)));

  const handleSendFriendRequest = async () => {
    if (!profileUser) return;

    try {
      await api.post('/users/friends/requests', {
        recipient_email: profileUser.email,
      });
      setFriendStatus('pending_sent');
    } catch (err) {
      console.error('Failed to send friend request:', err);
      alert(err.message || 'Failed to send friend request');
    }
  };

  const handleAcceptFriendRequest = async (requestId) => {
    try {
      await api.post(`/users/friends/requests/accept/${requestId}`);
      setFriendStatus('friends');
      // Refresh friends list if needed
    } catch (err) {
      console.error('Failed to accept friend request:', err);
      alert(err.message || 'Failed to accept friend request');
    }
  };

  if (loading) {
    return (
      <div className={styles.profile}>
        <div className={styles.container}>
          <div style={{ padding: '2rem', textAlign: 'center' }}>Loading...</div>
        </div>
      </div>
    );
  }

  if (error || !profileUser) {
    return (
      <div className={styles.profile}>
        <div className={styles.container}>
          <div style={{ padding: '2rem', textAlign: 'center' }}>
            {error || 'User not found'}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className={styles.profile}>
      <div className={styles.container}>
        {isOwnProfile ? (
          <ProfileHeader user={profileUser} />
        ) : (
          <ProfileHeaderVisitor 
            user={profileUser} 
            friendStatus={friendStatus}
            onSendFriendRequest={handleSendFriendRequest}
            onAcceptFriendRequest={handleAcceptFriendRequest}
          />
        )}
        <div className={styles.mainContent}>
          <div className={styles.leftColumn}>
            <About user={profileUser} />
            <Bio user={profileUser} />
          </div>
          <div className={styles.centerColumn}>
            <PostsFeed user={profileUser} />
          </div>
          <div className={styles.rightColumn}>
            <FriendsList user={profileUser} isOwnProfile={isOwnProfile} />
          </div>
        </div>
      </div>
    </div>
  );
}
